import { defineComponent } from 'vue'
import { each } from 'lodash';

import { withLegacyInlineTemplate } from '../../../libs/vue-inline-template'

export default withLegacyInlineTemplate(defineComponent({
    props: {
        primary: {
            type: [Number, String],
            required: false,
        },

        name: {
            type: String,
            required: true,
        },

        index: {
            type: [Number, String],
            required: false,
        },

        label: {
            type: String,
            required: false,
        },

        removed: {
            type: Boolean,
            default: false,
        },
    },

    computed: {
        canRemove() {
            return true;
        },
    },

    mounted() {
        each(this.$el.querySelectorAll('input, select, textarea'), (el) => {
            const id = el.getAttribute('id');
            //already taken into account for dependent select
            if (id && !(/_\d+$/.test(id))) {
                el.setAttribute('id', `${id}_${this.index}`);
            }
        });

        if (!this.primary) {
            each(this.$el.querySelectorAll('input, select, textarea'), (el) => {
                const name = el.getAttribute('name');
                if (name) {
                    let name_correct = name;
                    if (/\[]$/.test(name)) {
                        name_correct = name_correct.replace('[]', '') + '][';
                    }
                    el.setAttribute('name', `${this.name}[new_${this.index}][${name_correct}]`);
                }
            });
        }
    },

    methods: {
        destroyAdminComponents() {
            if (this.$el?.nodeType === 1) {
                Admin.Components.destroy(this.$el);
            }
        },

        handleRemove() {
            this.destroyAdminComponents();
            this.$emit('remove', this.primary, this.index);
        },
    },

    beforeDestroy() {
        this.destroyAdminComponents();
    },
}))
